document.addEventListener("DOMContentLoaded", () => {
  console.log("JS cargado ✅");

  // ======== VARIABLES GLOBALES ========
  const DOM = {
    // Elementos del menú
    menuToggle: document.getElementById("menu-toggle"),
    navLinks: document.getElementById("nav-links"),

  };

  const state = {
    currentHeroSlide: 0,
    heroSlideCount: DOM.heroSlides.length,
    heroInterval: null,
    scrollAmount: 300,
    autoScrollInterval: null,
    lastScrollTop: 0,
    sectionClosed: false,
    categoriaAbierta: null,
    tiendas: {
      moda: [{nombre: "Tienda A", url: "#"}, {nombre: "Tienda B", url: "#"}],
      electronica: [{nombre: "Tienda C", url: "#"}]
    }
  };

  // ======== FUNCIONES UTILITARIAS ========
  const utils = {
    debounce: (func, wait) => {
      let timeout;
      return function() {
        const context = this, args = arguments;
        clearTimeout(timeout);
        timeout = setTimeout(() => func.apply(context, args), wait);
      };
    },
    
    toggleElement: (element, className) => {
      element.classList.toggle(className);
    },
    
    closeElement: (element, className) => {
      element.classList.remove(className);
    }
  };

  // ======== MENÚ TOGGLE ========
  const initMenu = () => {
    DOM.menuToggle.addEventListener("click", () => {
      utils.toggleElement(DOM.navLinks, "active");
      utils.toggleElement(DOM.menuToggle, "active");
    });

    document.querySelectorAll(".nav-links a").forEach(link => {
      link.addEventListener("click", () => {
        if (window.innerWidth <= 992 && DOM.navLinks.classList.contains("active")) {
          utils.closeElement(DOM.navLinks, "active");
          utils.closeElement(DOM.menuToggle, "active");
        }
      });
    });
  };

  // ======== HERO CAROUSEL ========
  const initHeroCarousel = () => {
    DOM.heroSlides.forEach((_, index) => {
      const indicator = document.createElement('div');
      indicator.classList.add('indicator');
      if (index === 0) indicator.classList.add('active');
      indicator.addEventListener('click', () => goToSlide(index));
      DOM.indicatorsContainer.appendChild(indicator);
    });

    const indicators = document.querySelectorAll('.indicator');
    
    const updateCarousel = () => {
      DOM.heroTrack.style.transform = `translateX(-${state.currentHeroSlide * 100}%)`;
      indicators.forEach((indicator, index) => {
        indicator.classList.toggle('active', index === state.currentHeroSlide);
      });
    };
    
    const goToSlide = (index) => {
      state.currentHeroSlide = index;
      updateCarousel();
      resetAutoSlide();
    };
    
    const prevSlide = () => {
      state.currentHeroSlide = (state.currentHeroSlide - 1 + state.heroSlideCount) % state.heroSlideCount;
      updateCarousel();
      resetAutoSlide();
    };
    
    const nextSlide = () => {
      state.currentHeroSlide = (state.currentHeroSlide + 1) % state.heroSlideCount;
      updateCarousel();
      resetAutoSlide();
    };
    
    const startAutoSlide = () => {
      state.heroInterval = setInterval(nextSlide, 5000);
    };
    
    const resetAutoSlide = () => {
      clearInterval(state.heroInterval);
      startAutoSlide();
    };
    
    DOM.prevButton.addEventListener('click', prevSlide);
    DOM.nextButton.addEventListener('click', nextSlide);
    
    DOM.heroTrack.addEventListener('mouseenter', () => clearInterval(state.heroInterval));
    DOM.heroTrack.addEventListener('mouseleave', startAutoSlide);
    
    updateCarousel();
    startAutoSlide();
  };






  // ======== INICIALIZACIÓN ========
  const init = () => {
    initMenu();
    initHeroCarousel();
  };

  init();
});